      case "[":
        isOpen = true;
        break;
      case "]":
        isOpen = false;
        levels.push(level);
        level = new Set();
        break;
      default:
        if (isOpen) {
          level.add(c);
        } else {
          levels.push(new Set([c]));
        }
    }
